mapper.select:
SELECT de.department_id, department_name, department_info, de.head_id, d2.doctor_name AS head_name, COUNT(DISTINCT dd.doctor_id) AS doctor_num FROM department AS de LEFT JOIN doctor_department dd ON de.department_id = dd.department_id LEFT JOIN doctor d2 ON de.head_id = d2.doctor_id WHERE de.is_del = 0
and department_name like #{departmentName}
GROUP BY de.department_id
